INSERT INTO portfolio_sessions (date, mode, stance, summary, action_items) VALUES
  ('2026-06-02', 'live', 'Leaning into the tape. Added to the winners and opened a small NVDA call for convexity, sized well inside the options sleeve. Watching the inflation print midweek.', 'Risk-off lean. Volatility ticked up, so I cut the weakest position, parked the proceeds in cash, and resisted the urge to chase the bounce. Protecting the high-water mark matters more than being a hero here. The core stays intact; I would rather re-enter higher than ride a name I have lost conviction in.', 'Watch the call I opened into its catalyst; set a mental stop at the premium I paid. Reassess COST if it gaps. Earnings calendar is clear this week, so no print risk to manage.'),
  ('2026-06-03', 'live', 'Opportunistic. A gap down in GOOGL gave a cleaner entry than I expected, so I sized up with conviction. Otherwise holding.', 'Pressed the strongest names a touch and opened a small call for convexity into a catalyst, sized well inside the options sleeve. Checked earnings dates first so I am not holding into a surprise print. Left the steady compounders untouched. Leaning long and a bit aggressive, but every position still has a defined invalidation level.', 'Watch the call I opened into its catalyst; set a mental stop at the premium I paid. Reassess COST if it gaps. Earnings calendar is clear this week, so no print risk to manage.'),
  ('2026-06-04', 'live', 'Mostly housekeeping. Tilted toward the names beating the benchmark and away from the laggards. No new risk added.', 'Risk-off lean. Volatility ticked up, so I cut the weakest position, parked the proceeds in cash, and resisted the urge to chase the bounce. Protecting the high-water mark matters more than being a hero here. The core stays intact; I would rather re-enter higher than ride a name I have lost conviction in.', 'Watch the call I opened into its catalyst; set a mental stop at the premium I paid. Reassess COST if it gaps. Earnings calendar is clear this week, so no print risk to manage.'),
  ('2026-06-05', 'live', 'Added selectively and held the rest. The options sleeve is near its ceiling, so any new directional view goes through equity from here.', 'Pressed the strongest names a touch and opened a small call for convexity into a catalyst, sized well inside the options sleeve. Checked earnings dates first so I am not holding into a surprise print. Left the steady compounders untouched. Leaning long and a bit aggressive, but every position still has a defined invalidation level.', 'Defensive footing: if the drawdown deepens, trim the weakest name first. Otherwise hold and wait. Re-run the watchlist tomorrow and look for a re-entry higher.'),
  ('2026-06-08', 'live', 'Flat by design. Everything I own still earns its slot and the setups I am watching have not triggered. Cash is a position.', 'Quiet, deliberate day. Reviewed every holding, found the theses intact, and added a starter in a name on a clean pullback to its 50-day. Re-checked a resting exit from a prior session, saw it had filled, and updated the book. Running a touch defensive versus the index and watching the watchlist for tomorrow.', 'Defensive footing: if the drawdown deepens, trim the weakest name first. Otherwise hold and wait. Re-run the watchlist tomorrow and look for a re-entry higher.'),
  ('2026-06-09', 'live', 'Cautious add. Started UNH on weakness with a tight invalidation level. If it does not work I cut it fast; the cap math leaves room for one more name.', 'Started the session a little defensive after the open. Read the book and the tape, confirmed the core (MDT, COST) still earns its slot, and trimmed a bit of NVDA into strength to bank some gains. Added a small starter where the setup was clean. Net long but comfortable, with cash held back as dry powder. Watching the inflation print midweek before doing anything bigger.', 'Watch the call I opened into its catalyst; set a mental stop at the premium I paid. Reassess COST if it gaps. Earnings calendar is clear this week, so no print risk to manage.');
